-- events: created by `forge generate scaffold` for SQLite.
-- Identifiers are UUIDv7 values generated by the application; the
-- database never generates them. `version` is the optimistic lock.
-- Rows belong to a tenant. This backend has no row-level security
-- (ADR 0021): isolation rests on the application binding `tenant_id`
-- from the authorized TenantContext in every statement.

CREATE TABLE "events" (
    "id" BLOB NOT NULL PRIMARY KEY,
    "tenant_id" BLOB NOT NULL,
    "name" TEXT NOT NULL CONSTRAINT "events_name_length" CHECK (length("name") <= 255),
    "notes" TEXT,
    "starts_at" TEXT NOT NULL,
    "ends_at" TEXT,
    "capacity" INTEGER NOT NULL,
    "attendees" INTEGER,
    "public" INTEGER NOT NULL CONSTRAINT "events_public_boolean" CHECK ("public" IN (0, 1)),
    "featured" INTEGER CONSTRAINT "events_featured_boolean" CHECK ("featured" IN (0, 1)),
    "venue" BLOB NOT NULL,
    "organizer" BLOB,
    "version" INTEGER NOT NULL DEFAULT 1 CONSTRAINT "events_version_positive" CHECK ("version" >= 1),
    "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX "events_tenant_id_idx" ON "events" ("tenant_id", "id");
